<?php

declare(strict_types=1);

namespace DewanLab\LaravelZktecoAdmsCore\Services\Commands;

use DewanLab\LaravelZktecoAdmsCore\DTOs\CommandAck;
use DewanLab\LaravelZktecoAdmsCore\Enums\CommandStatus;
use DewanLab\LaravelZktecoAdmsCore\Models\ZkDevice;
use DewanLab\LaravelZktecoAdmsCore\Models\ZkDeviceCommand;

/**
 * Manages the asynchronous server-to-device command lifecycle in the ZKTeco ADMS Push Protocol.
 *
 * In the ADMS architecture, devices operate behind firewalls or NAT and cannot be contacted directly.
 * Instead, commands generated by the application are queued in the database (`zk_device_commands`)
 * with a `Pending` status. When a device periodically polls the server at `/iclock/getrequest`,
 * pending commands are batched and delivered in the wire protocol syntax:
 *
 * Wire payload format per command line:
 * `C:<CmdID>:<Command String>\n`
 *
 * Protocol constraints enforced:
 * - Maximum commands batched per cycle: 200 commands ({@see CommandQueueManager::MAX_BATCH_COUNT}).
 * - Maximum payload size per response: 40 KB / 40,960 bytes ({@see CommandQueueManager::MAX_PAYLOAD_BYTES}).
 * - Fallback response when queue is empty: `OK\n`.
 *
 * Lifecycle stages:
 * 1. Enqueued: Stored in database with status `Pending`.
 * 2. Sent: Delivered during `/iclock/getrequest` poll; marked as `Sent`.
 * 3. Acknowledged / Failed: Asynchronously reported via `/iclock/devicecmd`; marked as `Acknowledged` or `Failed`.
 *
 * Example:
 * ```php
 * $queueManager = app(CommandQueueManager::class);
 * $command = $queueManager->enqueue($device, 'REBOOT', 'REBOOT');
 * ```
 */
class CommandQueueManager
{
    /**
     * Maximum batched payload size in bytes (40 KB) allowable by device receive buffers.
     */
    public const MAX_PAYLOAD_BYTES = 40960;

    /**
     * Maximum number of commands delivered in a single /iclock/getrequest polling cycle.
     */
    public const MAX_BATCH_COUNT = 200;

    /**
     * Enqueue a command string for execution on a specific device.
     *
     * Persists the command record, assigns its unique command_id, and marks
     * its initial status as Pending.
     *
     * @param  ZkDevice  $device  Target hardware device model.
     * @param  string  $commandString  Raw ADMS wire-format command string (e.g. 'REBOOT', 'DATA UPDATE user ...').
     * @param  string  $type  Command classification type for tracking (e.g. 'DATA', 'REBOOT', 'RELAY').
     * @return ZkDeviceCommand The created and persisted command model.
     */
    public function enqueue(ZkDevice $device, string $commandString, string $type = 'DATA'): ZkDeviceCommand
    {
        $command = ZkDeviceCommand::create([
            'device_id' => $device->id,
            'command_id' => 0,
            'command_type' => $type,
            'command_string' => trim($commandString),
            'status' => CommandStatus::Pending,
            'queued_at' => now(),
        ]);

        $command->update(['command_id' => $command->id]);

        return $command;
    }

    /**
     * Enqueue multiple command strings sequentially for a device.
     *
     * Useful for operations requiring strict execution order, such as purging
     * previous access authorizations before applying updated permissions.
     *
     * @param  ZkDevice  $device  Target hardware device model.
     * @param  array<int, string>  $commandStrings  Ordered array of raw ADMS wire commands.
     * @param  string  $type  Command classification type for tracking.
     * @return array<int, ZkDeviceCommand> Array of created command models in order of insertion.
     */
    public function enqueueBatch(ZkDevice $device, array $commandStrings, string $type = 'DATA'): array
    {
        $queued = [];
        foreach ($commandStrings as $cmd) {
            $queued[] = $this->enqueue($device, $cmd, $type);
        }

        return $queued;
    }

    /**
     * Drain pending commands for a device formatted as ZKTeco wire payload.
     *
     * Queries pending commands up to {@see self::MAX_BATCH_COUNT}, enforces
     * the {@see self::MAX_PAYLOAD_BYTES} buffer limit, marks retrieved commands
     * as Sent, and returns formatted wire lines:
     * `C:<CmdID>:<Command String>\n`
     *
     * Returns "OK\n" if no commands are pending or eligible.
     *
     * @param  ZkDevice  $device  Device requesting pending commands via polling.
     * @return string Formatted wire payload string or "OK\n".
     */
    public function drainToWire(ZkDevice $device): string
    {
        $pending = ZkDeviceCommand::where('device_id', $device->id)
            ->where('status', CommandStatus::Pending)
            ->orderBy('id', 'asc')
            ->limit(self::MAX_BATCH_COUNT)
            ->get();

        if ($pending->isEmpty()) {
            return "OK\n";
        }

        $wirePayload = '';

        foreach ($pending as $cmd) {
            $line = sprintf("C:%d:%s\n", $cmd->command_id, $cmd->command_string);

            if (strlen($wirePayload.$line) > self::MAX_PAYLOAD_BYTES) {
                break;
            }

            $cmd->markAsSent();
            $wirePayload .= $line;
        }

        return $wirePayload !== '' ? $wirePayload : "OK\n";
    }

    /**
     * Process an asynchronous command execution acknowledgment callback.
     *
     * Matches the command by command_id, transitions its status to either
     * Acknowledged (if return code is 0) or Failed (if return code is non-zero),
     * and logs error details when available.
     *
     * @param  CommandAck  $ack  Parsed acknowledgment DTO received from /iclock/devicecmd.
     * @return ZkDeviceCommand|null The updated command model, or null if the command was not found.
     */
    public function acknowledge(CommandAck $ack): ?ZkDeviceCommand
    {
        $cmd = ZkDeviceCommand::where('command_id', $ack->commandId)->first();
        if ($cmd === null) {
            return null;
        }

        if ($ack->isSuccess()) {
            $cmd->markAsAcknowledged($ack->returnCode);
        } else {
            $cmd->markAsFailed($ack->returnCode, $ack->errorMessage());
        }

        return $cmd;
    }
}
